package com.example.myapplication;

import android.os.Bundle;
import android.view.View;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.Toast;
import android.widget.PopupMenu;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;

public class MainActivity extends AppCompatActivity implements CameraUiController {

    private LinearLayout slidingPanel;
    private ImageView btnToggle;
    private boolean isPanelExpanded = false;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_basic_mode);
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.viewFinder), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });

        // Initialize UI Components
        slidingPanel = findViewById(R.id.slidingPanel);
        btnToggle = findViewById(R.id.btnToggle);

        // Toggle Expand/Collapse
        btnToggle.setOnClickListener(v -> {
            isPanelExpanded = !isPanelExpanded;
            if (isPanelExpanded) {
                slidingPanel.setVisibility(View.VISIBLE);
                btnToggle.setImageResource(R.drawable.ic_arrow_up); // change to up arrow when expanded
            } else {
                slidingPanel.setVisibility(View.GONE);
                btnToggle.setImageResource(R.drawable.ic_arrow_down); // change to down arrow when collapsed
            }
        });

        // Setup Shutter Button
        findViewById(R.id.btnShutter).setOnClickListener(v -> onShutterClicked());
        // Setup Switch Camera Button
        findViewById(R.id.btnSwitch).setOnClickListener(v -> onSwitchCameraClicked());

        // Setup Top Bar Popups
        View topBar = findViewById(R.id.topBar);
        if (topBar != null) {
            View tvResolution = topBar.findViewById(R.id.tvResolution);
            if (tvResolution != null) {
                tvResolution.setOnClickListener(v -> {
                    PopupMenu popup = new PopupMenu(this, v);
                    popup.getMenu().add("48mp");
                    popup.getMenu().add("24mp");
                    popup.getMenu().add("12mp");
                    popup.setOnMenuItemClickListener(item -> {
                        Toast.makeText(this, "Resolution changed to " + item.getTitle(), Toast.LENGTH_SHORT).show();
                        return true;
                    });
                    popup.show();
                });
            }

            View tvAspectRatio = topBar.findViewById(R.id.tvAspectRatio);
            if (tvAspectRatio != null) {
                tvAspectRatio.setOnClickListener(v -> {
                    PopupMenu popup = new PopupMenu(this, v);
                    popup.getMenu().add("4:3");
                    popup.getMenu().add("16:9");
                    popup.getMenu().add("1:1");
                    popup.setOnMenuItemClickListener(item -> {
                        Toast.makeText(this, "Aspect Ratio changed to " + item.getTitle(), Toast.LENGTH_SHORT).show();
                        return true;
                    });
                    popup.show();
                });
            }
        }
    }

    @Override
    public void onShutterClicked() {
        Toast.makeText(this, "Shutter Clicked", Toast.LENGTH_SHORT).show();
    }

    @Override
    public void onSwitchCameraClicked() {
        Toast.makeText(this, "Switch Camera", Toast.LENGTH_SHORT).show();
    }

    @Override
    public void onZoomSelected(float zoomLevel) {
        Toast.makeText(this, "Zoom: " + zoomLevel + "x", Toast.LENGTH_SHORT).show();
    }

    @Override
    public void onModeChanged(boolean isVideoMode) {
        Toast.makeText(this, "Mode: " + (isVideoMode ? "Video" : "Photo"), Toast.LENGTH_SHORT).show();
    }

    @Override
    public void onPresetSelected(int presetIndex) {
        Toast.makeText(this, "Preset: " + presetIndex, Toast.LENGTH_SHORT).show();
    }
}

package com.example.myapplication;

import android.os.Bundle;
import android.view.View;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.Toast;
import android.widget.PopupMenu;
import android.widget.TextView;
import android.Manifest;
import android.content.pm.PackageManager;

import androidx.activity.EdgeToEdge;
import androidx.activity.result.ActivityResultLauncher;
import androidx.activity.result.contract.ActivityResultContracts;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.content.ContextCompat;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;

public class MainActivity extends AppCompatActivity implements CameraUiController {

    private LinearLayout slidingPanel;
    private ImageView btnToggle;
    private boolean isPanelExpanded = false;

    private CommandInvoker commandInvoker;
    private CameraSettingsStore settingsStore;
    private CameraManager cameraManager;

    private final ActivityResultLauncher<String[]> requestPermissionsLauncher =
            registerForActivityResult(new ActivityResultContracts.RequestMultiplePermissions(), permissions -> {
                boolean allGranted = true;
                for (Boolean isGranted : permissions.values()) {
                    if (!isGranted) allGranted = false;
                }
                if (allGranted) {
                    startCamera();
                } else {
                    Toast.makeText(this, "Permissions not granted by the user.", Toast.LENGTH_SHORT).show();
                }
            });

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_basic_mode);
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.viewFinder), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });

        // Initialize UI Components
        slidingPanel = findViewById(R.id.slidingPanel);
        btnToggle = findViewById(R.id.btnToggle);

        // Initialize Camera Backend
        settingsStore = new CameraSettingsStore();
        androidx.camera.view.PreviewView viewFinder = findViewById(R.id.viewFinder);
        cameraManager = new CameraManager(this, this, viewFinder);
        commandInvoker = new CommandInvoker(cameraManager, settingsStore);

        if (allPermissionsGranted()) {
            startCamera();
        } else {
            requestPermissionsLauncher.launch(new String[]{
                    Manifest.permission.CAMERA,
                    Manifest.permission.RECORD_AUDIO
            });
        }

        // Toggle Expand/Collapse
        btnToggle.setOnClickListener(v -> {
            isPanelExpanded = !isPanelExpanded;
            if (isPanelExpanded) {
                slidingPanel.setVisibility(View.VISIBLE);
                btnToggle.setImageResource(R.drawable.ic_arrow_up); // change to up arrow when expanded
            } else {
                slidingPanel.setVisibility(View.GONE);
                btnToggle.setImageResource(R.drawable.ic_arrow_down); // change to down arrow when collapsed
            }
        });

        // Setup Shutter Button
        findViewById(R.id.btnShutter).setOnClickListener(v -> onShutterClicked());
        // Setup Switch Camera Button
        findViewById(R.id.btnSwitch).setOnClickListener(v -> onSwitchCameraClicked());

        // Setup Top Bar Popups
        View topBar = findViewById(R.id.topBar);
        if (topBar != null) {
            View tvResolution = topBar.findViewById(R.id.tvResolution);
            if (tvResolution != null) {
                tvResolution.setOnClickListener(v -> {
                    PopupMenu popup = new PopupMenu(this, v);
                    popup.getMenu().add("48mp");
                    popup.getMenu().add("24mp");
                    popup.getMenu().add("12mp");
                    popup.setOnMenuItemClickListener(item -> {
                        commandInvoker.updateConfiguration(ConfigType.RESOLUTION, item.getTitle().toString());
                        ((TextView) tvResolution).setText(item.getTitle());
                        return true;
                    });
                    popup.show();
                });
            }

            View tvAspectRatio = topBar.findViewById(R.id.tvAspectRatio);
            if (tvAspectRatio != null) {
                tvAspectRatio.setOnClickListener(v -> {
                    PopupMenu popup = new PopupMenu(this, v);
                    popup.getMenu().add("4:3");
                    popup.getMenu().add("16:9");
                    popup.getMenu().add("1:1");
                    popup.setOnMenuItemClickListener(item -> {
                        commandInvoker.updateConfiguration(ConfigType.ASPECT_RATIO, item.getTitle().toString());
                        ((TextView) tvAspectRatio).setText(item.getTitle());
                        return true;
                    });
                    popup.show();
                });
            }
        }

        // Setup Zoom Buttons
        findViewById(R.id.btnZoom05).setOnClickListener(v -> onZoomSelected(0.5f));
        findViewById(R.id.btnZoom1).setOnClickListener(v -> onZoomSelected(1.0f));
        findViewById(R.id.btnZoom2).setOnClickListener(v -> onZoomSelected(2.0f));

        // Setup Photo/Video Toggle
        findViewById(R.id.slidingPanel).findViewById(R.id.btnPreset1).setOnClickListener(v -> onPresetSelected(1));
        findViewById(R.id.slidingPanel).findViewById(R.id.btnPreset2).setOnClickListener(v -> onPresetSelected(2));
        findViewById(R.id.slidingPanel).findViewById(R.id.btnPreset3).setOnClickListener(v -> onPresetSelected(3));
        findViewById(R.id.slidingPanel).findViewById(R.id.btnPreset4).setOnClickListener(v -> onPresetSelected(4));
        findViewById(R.id.slidingPanel).findViewById(R.id.btnPreset5).setOnClickListener(v -> onPresetSelected(5));

        // Pseudo implementation for Ev changing
        // In real app, you would use a SeekBar for EV
        View topBarLayout = findViewById(R.id.topBar);
        if (topBarLayout != null && topBarLayout.findViewById(R.id.tvEv) != null) {
            topBarLayout.findViewById(R.id.tvEv).setOnClickListener(v -> {
                float currentEv = settingsStore.getCurrentEv();
                float newEv = currentEv == 0f ? 1f : 0f; // Toggle EV for demo
                commandInvoker.updateConfiguration(ConfigType.EV, newEv);
                Toast.makeText(this, "EV changed to " + newEv, Toast.LENGTH_SHORT).show();
            });
        }
    }

    private boolean allPermissionsGranted() {
        return ContextCompat.checkSelfPermission(this, Manifest.permission.CAMERA) == PackageManager.PERMISSION_GRANTED
                && ContextCompat.checkSelfPermission(this, Manifest.permission.RECORD_AUDIO) == PackageManager.PERMISSION_GRANTED;
    }

    private void startCamera() {
        commandInvoker.setCaptureMode(settingsStore.getCaptureMode());
    }

    @Override
    public void onShutterClicked() {
        if (settingsStore.getCaptureMode() == CaptureMode.PHOTO) {
            commandInvoker.takePhoto();
        } else {
            if (settingsStore.getCameraState() == CameraState.RECORDING) {
                commandInvoker.stopRecording();
            } else {
                commandInvoker.startRecording();
            }
        }
    }

    @Override
    public void onSwitchCameraClicked() {
        commandInvoker.switchCamera();
    }

    @Override
    public void onZoomSelected(float zoomLevel) {
        commandInvoker.setZoomRatio(zoomLevel);
        Toast.makeText(this, "Zoom set to " + zoomLevel + "x", Toast.LENGTH_SHORT).show();
    }

    @Override
    public void onModeChanged(boolean isVideoMode) {
        CaptureMode mode = isVideoMode ? CaptureMode.VIDEO : CaptureMode.PHOTO;
        commandInvoker.setCaptureMode(mode);
        Toast.makeText(this, "Changed to " + mode + " mode", Toast.LENGTH_SHORT).show();
    }

    @Override
    public void onPresetSelected(int presetIndex) {
        commandInvoker.applyPreset(presetIndex);
        Toast.makeText(this, "Preset " + presetIndex + " applied", Toast.LENGTH_SHORT).show();
    }
}
